    const promptLower = options.prompt.toLowerCase();
    const pageId = `page-ai-${nanoid(6)}`;
    const now = new Date().toISOString();

    let title = options.pageTitle || 'Сгенерированная страница';
    let slug = 'ai-page';
    let rawBlocks: z.infer<typeof AiGeneratedBlockSchema>[] = [];

